import{_ as e,o as s,c as a,a2 as t}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"Export und Import","description":"","frontmatter":{},"headers":[],"relativePath":"de/advanced/export-import.md","filePath":"de/advanced/export-import.md","lastUpdated":1784904021000}'),n={name:"de/advanced/export-import.md"};function p(h,i,r,l,d,o){return s(),a("div",null,[...i[0]||(i[0]=[t(`<h1 id="export-und-import" tabindex="-1">Export und Import <a class="header-anchor" href="#export-und-import" aria-label="Permalink to &quot;Export und Import&quot;">​</a></h1><h2 id="ubersicht" tabindex="-1">Übersicht <a class="header-anchor" href="#ubersicht" aria-label="Permalink to &quot;Übersicht&quot;">​</a></h2><p>swag2mcp unterstützt die vollständige Arbeitsbereichs-Roundtrip-Funktionalität über ZIP-Archive. Sie können Ihren gesamten Arbeitsbereich (Konfiguration, Spezifikationsdateien, Authentifizierungsskripte) in eine ZIP-Datei exportieren und auf einem anderen Rechner wiederherstellen.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Erstellt ein portables ZIP-Backup Ihres Arbeitsbereichs.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In Standarddatei exportieren (swag2mcp-backup-&amp;lt;timestamp&amp;gt;.zip)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Mit benutzerdefiniertem Pfad exportieren</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/backups/swag2mcp-backup.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Nur bestimmte Specs exportieren</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo,store</span></span></code></pre></div><h3 id="was-im-export-enthalten-ist" tabindex="-1">Was im Export enthalten ist <a class="header-anchor" href="#was-im-export-enthalten-ist" aria-label="Permalink to &quot;Was im Export enthalten ist&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Element</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>swag2mcp.yaml</code></td><td>Konfigurationsdatei</td></tr><tr><td><code>specs/</code></td><td>Alle Spezifikationsdateien (OpenAPI/Swagger/Postman)</td></tr><tr><td><code>auth_scripts/</code></td><td>Authentifizierungsskripte</td></tr><tr><td><code>swag2mcp.meta</code></td><td>Metadaten (Versionsinfo für Kompatibilität)</td></tr></tbody></table><p>Cache und Antworten werden <strong>nicht</strong> exportiert — sie sind flüchtig und wären bei der Wiederherstellung veraltet.</p><h3 id="standard-dateiname" tabindex="-1">Standard-Dateiname <a class="header-anchor" href="#standard-dateiname" aria-label="Permalink to &quot;Standard-Dateiname&quot;">​</a></h3><p>Wenn Sie keinen Ausgabepfad angeben, wird die Datei als <code>swag2mcp-backup-&lt;YYYY-MM-DD-HHMMSS&gt;.zip</code> im aktuellen Verzeichnis gespeichert (UTC-Zeitstempel).</p><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><p>Stellen Sie einen Arbeitsbereich aus einem ZIP-Backup wieder her oder importieren Sie Spezifikationsdateien.</p><h3 id="aus-zip-wiederherstellen" tabindex="-1">Aus ZIP wiederherstellen <a class="header-anchor" href="#aus-zip-wiederherstellen" aria-label="Permalink to &quot;Aus ZIP wiederherstellen&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Vollständigen Arbeitsbereich wiederherstellen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /pfad/zu/sicherung.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Mit Überschreiben wiederherstellen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /pfad/zu/sicherung.zip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div><p>Das ZIP muss von <code>swag2mcp export</code> erstellt worden sein — beliebige ZIP-Dateien funktionieren nicht.</p><h3 id="einzelne-spezifikationsdatei-importieren" tabindex="-1">Einzelne Spezifikationsdatei importieren <a class="header-anchor" href="#einzelne-spezifikationsdatei-importieren" aria-label="Permalink to &quot;Einzelne Spezifikationsdatei importieren&quot;">​</a></h3><p>Laden Sie eine Spezifikationsdatei herunter und fügen Sie sie zum Arbeitsbereich hinzu:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com/spec.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myspec</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /pfad/zu/arbeitsbereich</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com/spec.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myspec</span></span></code></pre></div><h3 id="massenimport-aus-bestehender-konfiguration" tabindex="-1">Massenimport aus bestehender Konfiguration <a class="header-anchor" href="#massenimport-aus-bestehender-konfiguration" aria-label="Permalink to &quot;Massenimport aus bestehender Konfiguration&quot;">​</a></h3><p>Laden Sie alle Collection-Spezifikationsdateien für die angegebenen Specs (Domains) herunter:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /pfad/zu/arbeitsbereich</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo,store</span></span></code></pre></div><p>Dies lädt die Spezifikationsdatei jeder Collection herunter, speichert sie in <code>specs/</code> und aktualisiert die Konfiguration, um auf die lokale Kopie zu verweisen.</p><h2 id="anwendungsfalle" tabindex="-1">Anwendungsfälle <a class="header-anchor" href="#anwendungsfalle" aria-label="Permalink to &quot;Anwendungsfälle&quot;">​</a></h2><h3 id="backup" tabindex="-1">Backup <a class="header-anchor" href="#backup" aria-label="Permalink to &quot;Backup&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%Y-%m-%d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.zip</span></span></code></pre></div><h3 id="auf-einen-anderen-rechner-ubertragen" tabindex="-1">Auf einen anderen Rechner übertragen <a class="header-anchor" href="#auf-einen-anderen-rechner-ubertragen" aria-label="Permalink to &quot;Auf einen anderen Rechner übertragen&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Auf altem Rechner</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ZIP auf den neuen Rechner kopieren, dann:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp.zip</span></span></code></pre></div><h3 id="konfiguration-teilen" tabindex="-1">Konfiguration teilen <a class="header-anchor" href="#konfiguration-teilen" aria-label="Permalink to &quot;Konfiguration teilen&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> template.zip</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># template.zip mit einem Kollegen teilen</span></span></code></pre></div><h2 id="uberprufung-nach-dem-export" tabindex="-1">Überprüfung nach dem Export <a class="header-anchor" href="#uberprufung-nach-dem-export" aria-label="Permalink to &quot;Überprüfung nach dem Export&quot;">​</a></h2><p>Überprüfen Sie immer, ob die ZIP-Datei erstellt wurde:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -la</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp-backup-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.zip</span></span></code></pre></div><h2 id="wichtige-hinweise" tabindex="-1">Wichtige Hinweise <a class="header-anchor" href="#wichtige-hinweise" aria-label="Permalink to &quot;Wichtige Hinweise&quot;">​</a></h2><ul><li><strong>Die Ausgabe muss ein Dateipfad sein, der auf <code>.zip</code> endet</strong> — übergeben Sie kein Verzeichnis</li><li><strong>Cache und Antworten sind ausgeschlossen</strong> — nur die Konfiguration, Spezifikationen und Authentifizierungsskripte werden gespeichert</li><li><strong>Das ZIP ist in sich geschlossen</strong> — es kann auf jedem Rechner mit installiertem swag2mcp wiederhergestellt werden</li><li><strong>Spec-Filter</strong> — verwenden Sie <code>--spec</code>, um nur bestimmte Specs zu exportieren oder zu importieren</li></ul>`,35)])])}const g=e(n,[["render",p]]);export{c as __pageData,g as default};
